initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response containing:
        Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData' and
        Response body containing 'title' element and
        Response Status Code set to 400
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entities/'
        method set to 'GET'
        Request Query Entities with entity_ids set to 'entity_id_pattern=${invalid_entity_id_pattern}' with entity_types set to '${entity_types_to_be_retrieved}
